const LOYALTY_DISCOUNT = 0.2;
const LOYALTY_THRESHOLD_YEARS = 2;

const isLoyal = (customer: Customer): boolean =>
  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;

const loyaltyDiscount = (policyBase: number, customer: Customer): number =>
  isLoyal(customer) ? policyBase * LOYALTY_DISCOUNT : 0;

const FOLLOW_UP_CONTRACT_DISCOUNT = 0.15;

const followUpContractDiscount = (policyBase: number, previousContracts: number): number =>
  previousContracts > 0 ? policyBase * FOLLOW_UP_CONTRACT_DISCOUNT : 0;

const policyWidePremium = (
  policyBase: number,
  customer: Customer,
  previousContracts: number,
): number =>
  withFirstInsuranceSurcharge(policyBase) -
  loyaltyDiscount(policyBase, customer) -
  followUpContractDiscount(policyBase, previousContracts);

const premiumBeforeFee = (
  items: Item[],
  customer: Customer,
  previousContracts: number,
): number =>
  policyWidePremium(policyBasePremium(items), customer, previousContracts) +
  totalRiskSurcharges(items);

const quotePremium = (
  items: Item[],
  customer: Customer,
  previousContracts: number,
): number =>
  roundPremiumInMHPCOsFavor(
    premiumBeforeFee(items, customer, previousContracts) + PROCESSING_FEE,
  );

export const runScenario = (scenario: Scenario): ScenarioResult => {
  const results: StepResult[] = [];
  let contracts = 0;

  for (const step of scenario.steps) {
    if (step.op !== "quote") {
      throw new Error(`Unsupported step: ${step.op}`);
    }
    results.push({ premium: quotePremium(step.items, scenario.customer, contracts) });
    contracts += 1;
  }

  return { results };
};

